krpano.action:
tween(hotspot[%1].borderwidth, 3, 1);
tween(hotspot[%1].bordercolor, 0xffffff);
delayedcall(1.0, tween(hotspot[%1].borderwidth, 1, 1); );
delayedcall(2, polygonhotspot_blink(%1); );

if(keycode == 81, polytool_toggle(); );
if(polytool_on,
	if(keycode == 13, polytool_finish(); );
	if(keycode == 27, polytool_clear(); polytool_status(); );
	if(keycode == 90, polytool_undo(); );
);

if(polytool_on,
	set(polytool_on, false);
	polytool_clear();
	set(layer[polytool_capture].visible, false);
	set(layer[polytool_hint].visible, false);
,
	set(polytool_on, true);
	polytool_clear();
	set(layer[polytool_capture].visible, true);
	set(layer[polytool_hint].visible, true);
	polytool_status();
);

set(hit, -1);
copy(n, hotspot[polytool_poly].point.count);

for(set(i,0), i LT n, inc(i),
	spheretoscreen(hotspot[polytool_poly].point[get(i)].ath,
	               hotspot[polytool_poly].point[get(i)].atv, px, py);
	sub(dx, get(px), get(mouse.stagex));
	sub(dy, get(py), get(mouse.stagey));
	mul(dx, get(dx));
	mul(dy, get(dy));
	add(d2, get(dx), get(dy));

	if(d2 LT 576,
		set(hit, get(i));
		copy(i, n);
	);
);

if(hit GE 0,
	polytool_dragpoint(get(hit));
,
	polytool_addpoint();
);

set(layer[polytool_hint].html, 'Đang kéo đỉnh — thả chuột để chốt');
asyncloop(layer[polytool_capture].pressed,
	screentosphere(mouse.stagex, mouse.stagey, dath, datv);
	set(hotspot[polytool_poly].point[%1].ath, get(dath));
	set(hotspot[polytool_poly].point[%1].atv, get(datv));
	txtadd(dn, 'polytool_dot_', %1);
	copy(hotspot[get(dn)].ath, dath);
	copy(hotspot[get(dn)].atv, datv);
  ,
	polytool_status();
);

screentosphere(mouse.stagex, mouse.stagey, pt_ath, pt_atv);
copy(idx, hotspot[polytool_poly].point.count);

hotspot[polytool_poly].point.createarrayitem(get(idx));
set(hotspot[polytool_poly].point[get(idx)].ath, get(pt_ath));
set(hotspot[polytool_poly].point[get(idx)].atv, get(pt_atv));

txtadd(dotname, 'polytool_dot_', get(idx));
addhotspot(get(dotname));
hotspot[get(dotname)].loadstyle(polytool_dot);
copy(hotspot[get(dotname)].ath, pt_ath);
copy(hotspot[get(dotname)].atv, pt_atv);

if(hotspot[polytool_poly].point.count GE 3,
	set(hotspot[polytool_poly].visible, true);
);


polytool_dragpoint(get(idx));

copy(n, hotspot[polytool_poly].point.count);
if(n GT 0,
	dec(n);
	txtadd(dotname, 'polytool_dot_', get(n));
	removehotspot(get(dotname));
	hotspot[polytool_poly].point.removearrayitem(get(n));
	if(hotspot[polytool_poly].point.count LT 3,
		set(hotspot[polytool_poly].visible, false);
	);
	polytool_status();
);

copy(n, hotspot[polytool_poly].point.count);
for(set(i,0), i LT n, inc(i),
	txtadd(dotname, 'polytool_dot_', get(i));
	removehotspot(get(dotname));
);
for(copy(k, n), k GT 0, dec(k),
	hotspot[polytool_poly].point.removearrayitem( calc(k - 1) );
);
set(hotspot[polytool_poly].visible, false);

txtadd(msg,
	'[b]VẼ POLYGON[/b] — ', get(hotspot[polytool_poly].point.count), ' đỉnh[br]',
	'Bấm nền để thêm đỉnh · kéo chấm để dời[br]',
	'[b]Z[/b] bỏ đỉnh cuối · [b]Esc[/b] xoá hết[br]',
	'[b]Enter[/b] xuất XML · [b]Q[/b] thoát');
set(layer[polytool_hint].html, get(msg));

copy(n, hotspot[polytool_poly].point.count);
if(n LT 3,
	set(layer[polytool_hint].html, 'Cần ít nhất 3 đỉnh mới tạo được polygon.');
,
	set(out, '');
	txtadd(out, get(out), '<hotspot name="poly1" style="mypolygonalhotspotstylename">[br]');
	for(set(i,0), i LT n, inc(i),
		txtadd(out, get(out),
			'    <point ath="', get(hotspot[polytool_poly].point[get(i)].ath),
			'" atv="', get(hotspot[polytool_poly].point[get(i)].atv), '" />[br]');
	);
	txtadd(out, get(out), '</hotspot>');

	set(layer[polytool_dump].html, '');
	txtadd(layer[polytool_dump].html,
		'[b]Dán khối này vào <scene> trong tour.xml[/b][br]',
		'Đổi name="poly1" cho khác nhau nếu một scene có nhiều polygon.[br][br]',
		get(out));
	set(layer[polytool_dump].visible, true);
	set(layer[polytool_dumpclose].visible, true);
);
